using System.Reflection;
using System.Xml.Linq;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public sealed class ArchitectureTests
{
    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(AuthorizePayment).Assembly;

    [Theory]
    [InlineData("PaymentAuthorization.Domain")]
    [InlineData("PaymentAuthorization.Application", "PaymentAuthorization.Domain")]
    [InlineData("PaymentAuthorization.Infrastructure", "PaymentAuthorization.Application")]
    public void Project_ReferencesOnlyItsInnerNeighbour(string project, params string[] allowed)
    {
        var references = XDocument.Load(ProjectFile(project))
            .Descendants("ProjectReference")
            .Select(reference => Path.GetFileNameWithoutExtension(((string)reference.Attribute("Include")!).Replace('\\', '/')))
            .Order()
            .ToArray();

        Assert.Equal(allowed.Order().ToArray(), references);
    }

    [Fact]
    public void Domain_DependsOnlyOnItselfAndTheLanguageCore()
        => AssertOnly(DomainAssembly, "PaymentAuthorization.Domain");

    [Fact]
    public void Application_DependsOnlyOnInnerLayersAndTheLanguageCore()
        => AssertOnly(ApplicationAssembly, "PaymentAuthorization.Application", "PaymentAuthorization.Domain");

    [Fact]
    public void Infrastructure_IsReachedFromTheTestsOnlyThroughItsOwnAssembly()
        => Assert.Equal("PaymentAuthorization.Infrastructure", typeof(FileSystemReceiptStore).Assembly.GetName().Name);

    private static string ProjectFile(string project)
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !directory.EnumerateFiles("*.sln*").Any())
            directory = directory.Parent;

        return Path.Combine(directory!.FullName, "src", project, $"{project}.csproj");
    }

    // `System` is the base library; I/O, network and persistence inside it are technical details too.
    private static void AssertOnly(Assembly assembly, params string[] layers)
    {
        var tools = ToolNamespaces(assembly);
        var frameworks = Business(assembly, tools)
            .Should().OnlyHaveDependenciesOn([.. layers, "System", .. tools, .. Generated(assembly)])
            .GetResult();
        var io = Business(assembly, tools)
            .Should().NotHaveDependencyOnAny("System.IO", "System.Net", "System.Data")
            .GetResult();

        Assert.True(frameworks.IsSuccessful, Format(frameworks));
        Assert.True(io.IsSuccessful, Format(io));
    }

    // Namespaces Coverlet and Stryker.NET add hold no business code.
    private static string[] ToolNamespaces(Assembly assembly) => assembly.GetTypes()
        .Select(type => type.Namespace)
        .OfType<string>()
        .Where(name => name.StartsWith("Coverlet.Core.Instrumentation", StringComparison.Ordinal)
            || name.StartsWith("Stryker", StringComparison.Ordinal))
        .Distinct()
        .ToArray();

    // Compiler-generated `<…>` types are out of the scan by name and allowed by full name.
    private static string[] Generated(Assembly assembly) => assembly.GetTypes()
        .Where(type => type.DeclaringType is null && type.Name.StartsWith('<'))
        .Select(type => type.FullName!)
        .ToArray();

    private static PredicateList Business(Assembly assembly, string[] tools)
        => tools.Aggregate(Types.InAssembly(assembly).That().DoNotHaveNameStartingWith("<"),
            (types, name) => types.And().DoNotResideInNamespace(name));

    private static string Format(TestResult result)
        => $"Violations: {string.Join(", ", result.FailingTypeNames ?? Array.Empty<string>())}";
}
